def markersets(g):
    c=Counter(v for r in g for v in r); bg=c.most_common(1)[0][0]
    ms={}
    ms['nonbg']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg]
    ms['nonbg0']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg and v!=0]
    ms['nonbg01']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v not in (bg,0,1)]
    for k in (1,2,3,4):
        ms[f'cnt{k}']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg and c[v]==k]
        ms[f'cntle{k}']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg and c[v]<=k]
    ms['ones']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==1]
    ms['bg']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==bg]
    ms['zeros']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==0]
    ms['ge5']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v>=5]
    ms['even']=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg and v%2==0]
    return ms
