def adj_cells(g,i,j):
    out=[]
    for di in(-1,0,1):
        for dj in(-1,0,1):
            if di==dj==0: continue
            a,b_=i+di,j+dj
            if 0<=a<7 and 0<=b_<7: out.append(g[a][b_])
    return out
