from collections import deque
def bfs_path(g, start, goal, passable):
    q=deque([start]); prev={start:None}
    while q:
        cur=q.popleft()
        if cur==goal: break
        i,j=cur
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b_=i+di,j+dj
            if 0<=a<7 and 0<=b_<7 and (a,b_) not in prev and passable(g[a][b_],a,b_):
                prev[(a,b_)]=cur; q.append((a,b_))
    if goal not in prev: return None
    path=[]; c=goal
    while c: path.append(c); c=prev[c]
    return path
