NB8=[(di,dj) for di in(-1,0,1) for dj in(-1,0,1) if (di,dj)!=(0,0)]
NB4=[(1,0),(-1,0),(0,1),(0,-1)]
def feats(g, wall, ddpos):
    out={}
    wcells={(i,j) for i in range(7) for j in range(7) if g[i][j]==wall}
    zcells={(i,j) for i in range(7) for j in range(7) if g[i][j]==0}
    # wall degree (8-conn) among wall cells: ends vs junctions
    out['wall_deg3']={c for c in wcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)>=3}
    out['wall_deg1']={c for c in wcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)<=1}
    out['wall_deg4']={c for c in wcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)>=4}
    # 0-cells with many wall neighbors
    out['z_wall3']={c for c in zcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)>=3}
    out['z_wall4']={c for c in zcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)>=4}
    out['z_wall2']={c for c in zcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)>=2}
    out['z_wall0']={c for c in zcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in wcells)==0}
    # wall cells adjacent to dots
    out['wall_adj_dot']={c for c in wcells if any((c[0]+di,c[1]+dj) in ddpos for di,dj in NB8)}
    # 0-cells adjacent to dots
    out['z_adj_dot']={c for c in zcells if any((c[0]+di,c[1]+dj) in ddpos for di,dj in NB8)}
    out['z_adj2dot']={c for c in zcells if sum(1 for di,dj in NB8 if (c[0]+di,c[1]+dj) in ddpos)>=2}
    # dots themselves, dots+adjacent
    out['dots']=set(ddpos)
    out['dots+1']={ (c[0]+di,c[1]+dj) for c in ddpos for di,dj in NB8 if 0<=c[0]+di<7 and 0<=c[1]+dj<7 }
    # BFS from each dot over 0s to nearest wall; path cells
    paths=set()
    for c in ddpos:
        prev={c:None}; q=deque([c])
        while q:
            cur=q.popleft()
            if cur in wcells: break
            for di,dj in NB4:
                a,b_=cur[0]+di,cur[1]+dj
                if 0<=a<7 and 0<=b_<7 and (a,b_) not in prev and g[a][b_] in (0,) or (a,b_) in ddpos:
                    prev[(a,b_)]=cur; q.append((a,b_))
        # skip if unreachable
        cc2=None
        for cell in prev:
            if cell in wcells: cc2=cell; break
        if cc2:
            x=cc2
            while x is not None:
                paths.add(x); x=prev[x]
    out['dot_to_wall_paths']=paths
    return out
